void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  group('wedgeMask constant matches SW getWedgeMask', () {
    // The SW exposes only the wedge-enabled sizes as non-null. Confirm our
    // isWedgeUsed mirror agrees over the full BLOCK_SIZES_ALL range.
    test('isWedgeUsed agrees with SW over all block sizes', () {
      for (var b = 0; b < 22; b++) {
        expect(
          HarborWedgeMask.isWedgeUsed(b),
          equals(_isWedgeUsedGold[b]),
          reason: 'isWedgeUsed mismatch at bSize=$b',
        );
      }
    });

    for (final b in _wedgeSizes) {
      for (final index in [0, 1, 2, 3, 4, 7, 8, 12, 15]) {
        for (final sign in [0, 1]) {
          test('bSize=$b index=$index sign=$sign', () {
            final gold = _wedgeGold['${b}_${index}_$sign']!;
            final got = HarborWedgeMask.wedgeMask(b, index, sign);
            expect(
              got.length,
              equals(gold.length),
              reason: 'length mismatch bSize=$b idx=$index sign=$sign',
            );
            expect(
              got,
              equals(gold),
              reason: 'mask mismatch bSize=$b idx=$index sign=$sign',
            );
            // Every value is a 7-bit weight in 0..64.
            for (final v in got) {
              expect(v, inInclusiveRange(0, 64));
            }
          });
        }
      }
    }
  });

  group('HarborWedgeMask ROHD module drives constant mask', () {
    // A few representative configs across sizes/indices/signs.
    final configs = <(int, int, int)>[
      (3, 0, 0),
      (3, 5, 1),
      (6, 8, 0),
      (9, 15, 1),
      (18, 2, 0),
      (19, 12, 1),
    ];

    for (final (b, index, sign) in configs) {
      test('module mask port bSize=$b index=$index sign=$sign', () async {
        final bw = _bw[b], bh = _bh[b];
        final n = bw * bh;
        final mod = HarborWedgeMask(bSize: b, wedgeIndex: index, sign: sign);
        await mod.build();
        Simulator.setMaxSimTime(1000);
        unawaited(Simulator.run());

        final gold = HarborWedgeMask.wedgeMask(b, index, sign);
        final maskVal = mod.output('mask').value;
        expect(mod.output('mask').width, equals(n * 7));
        for (var k = 0; k < n; k++) {
          final v = maskVal.getRange(k * 7, k * 7 + 7).toInt();
          expect(
            v,
            equals(gold[k]),
            reason: 'module mask k=$k bSize=$b idx=$index sign=$sign',
          );
        }
        await Simulator.endSimulation();
      });
    }
  });

  test('HarborWedgeMask rejects non-wedge block size', () {
    expect(
      () => HarborWedgeMask(bSize: 0, wedgeIndex: 0, sign: 0),
      throwsA(isA<ArgumentError>()),
    );
  });

  test('HarborWedgeMask rejects out-of-range wedge index', () {
    expect(
      () => HarborWedgeMask(bSize: 3, wedgeIndex: 16, sign: 0),
      throwsA(isA<ArgumentError>()),
    );
  });

  test('HarborWedgeMask rejects out-of-range sign', () {
    expect(
      () => HarborWedgeMask(bSize: 3, wedgeIndex: 0, sign: 2),
      throwsA(isA<ArgumentError>()),
    );
  });
}
